# Let me search the FULL json content more thoroughly for any 2025 data
import json

with open('/app/resources/treasury_bulletin_2014_06.json', 'r') as f:
    data = json.load(f)

# Search recursively for any '2025' keys or values
def find_2025(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if '2025' in str(k):
                results.append(f'Key: {path}.{k}')
            results.extend(find_2025(v, f'{path}.{k}'))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(find_2025(item, f'{path}[{i}]'))
    elif isinstance(obj, str):
        if '2025' in obj:
            results.append(f'String at {path}: {obj[:100]}')
    return results

results = find_2025(data)
print(f'Found {len(results)} results')
for r in results[:10]:
    print(r)"

